export interface ConnectorConfig {
  githubOwner: string
  githubRepo: string
  githubToken: string
  zendeskSubdomain: string
  zendeskToken: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  account_id: number
  detail: {
    actor_id: string
    assignee_id: string
    brand_id: string
    created_at: string
    custom_status: string
    description: string
    external_id: string | null
    form_id: string
    group_id: string
    id: string
    is_public: boolean
    organization_id: string
    priority: string
    requester_id: string
    status: string
    subject: string
    submitter_id: string
    tags: string[]
    type: string | null
    updated_at: string
    via: { channel: string }
  }
  event: {
    current: string
    meta: { sequence: { id: string; position: number } }
    previous: string | null
  }
  id: string
  subject: string
  time: string
  type: string
  zendesk_event_version: string
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

interface GitHubIssue {
  number: number
  title: string
  body: string
  html_url: string
}

interface GitHubListResponse {
  items: GitHubIssue[]
}

interface GitHubCreateResponse {
  number: number
  html_url: string
}

interface ZendeskCommentResponse {
  comment: {
    id: number
    body: string
    public: boolean
  }
}

async function searchGitHubIssue(
  title: string,
  config: ConnectorConfig,
): Promise<GitHubIssue | null> {
  const fetch = config.fetch ?? globalThis.fetch
  const url = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues?per_page=100`
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'User-Agent': 'patchbay-connector',
    },
  })

  if (!response.ok) {
    throw new Error(`GitHub list issues failed: ${response.status} ${response.statusText} at ${url}`)
  }

  const data = (await response.json()) as GitHubListResponse
  return data.items.find((issue) => issue.title === title) ?? null
}

async function createGitHubIssue(
  title: string,
  body: string,
  config: ConnectorConfig,
): Promise<GitHubCreateResponse> {
  const fetch = config.fetch ?? globalThis.fetch
  const url = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'User-Agent': 'patchbay-connector',
    },
    body: JSON.stringify({ title, body }),
  })

  if (!response.ok) {
    throw new Error(`GitHub create issue failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return (await response.json()) as GitHubCreateResponse
}

async function postZendeskComment(
  ticketId: string,
  commentBody: string,
  config: ConnectorConfig,
): Promise<ZendeskCommentResponse> {
  const fetch = config.fetch ?? globalThis.fetch
  const url = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ comment: { body: commentBody, public: true } }),
  })

  if (!response.ok) {
    throw new Error(`Zendesk create comment failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return (await response.json()) as ZendeskCommentResponse
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id')
  }

  const title = payload.detail.subject
  const body = payload.detail.description
  const ticketId = payload.detail.id

  const existingIssue = await searchGitHubIssue(title, config)

  let issueNumber: number
  let issueUrl: string

  if (existingIssue) {
    issueNumber = existingIssue.number
    issueUrl = existingIssue.html_url
  } else {
    const created = await createGitHubIssue(title, body, config)
    issueNumber = created.number
    issueUrl = created.html_url
  }

  const commentResponse = await postZendeskComment(
    ticketId,
    `GitHub issue created: ${issueUrl}`,
    config,
  )

  return {
    githubIssueNumber: issueNumber,
    githubIssueUrl: issueUrl,
    zendeskCommentId: commentResponse.comment.id,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'example',
      githubToken: 'gh_test_token',
      zendeskSubdomain: 'testsub',
      zendeskToken: 'zd_test_token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/example/issues/42')
    expect(result.zendeskCommentId).toBe(12345)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      githubOwner: 'octocat',
      githubRepo: 'example',
      githubToken: 'gh_test_token',
      zendeskSubdomain: 'testsub',
      zendeskToken: 'zd_test_token',
    }
    calls = []
  })

  it('happy path: searches, finds existing issue, posts comment', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/repos/octocat/example/issues') && req.method === 'GET') {
        return jsonResponse({
          items: [
            { number: 42, title: 'Alpha top - group over queue', body: 'OCR Queues Regression Tests', html_url: 'https://github.com/octocat/example/issues/42' },
          ],
        })
      }
      if (req.url.includes('/tickets/14038/comments.json') && req.method === 'POST') {
        return jsonResponse({ comment: { id: 999, body: 'GitHub issue created: https://github.com/octocat/example/issues/42', public: true } })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'Alpha top - group over queue', description: 'OCR Queues Regression Tests', id: '14038' },
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/example/issues/42')
    expect(result.zendeskCommentId).toBe(999)

    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toBe('https://api.github.com/repos/octocat/example/issues?per_page=100')
    expect(calls[0].headers.get('authorization')).toBe('Bearer gh_test_token')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://testsub.zendesk.com/api/v2/tickets/14038/comments.json')
    expect(calls[1].json).toEqual({ comment: { body: 'GitHub issue created: https://github.com/octocat/example/issues/42', public: true } })
    expect(calls[1].headers.get('authorization')).toBe('Bearer zd_test_token')
  })

  it('happy path: searches, creates new issue when not found, posts comment', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/repos/octocat/example/issues') && req.method === 'GET') {
        return jsonResponse({ items: [] })
      }
      if (req.url.includes('/repos/octocat/example/issues') && req.method === 'POST') {
        expect(req.json).toEqual({ title: 'New Ticket Title', body: 'New ticket description' })
        return jsonResponse({ number: 43, html_url: 'https://github.com/octocat/example/issues/43' }, 201)
      }
      if (req.url.includes('/tickets/14038/comments.json') && req.method === 'POST') {
        return jsonResponse({ comment: { id: 1000, body: 'GitHub issue created: https://github.com/octocat/example/issues/43', public: true } })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'New Ticket Title', description: 'New ticket description', id: '14038' },
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(43)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/example/issues/43')
    expect(result.zendeskCommentId).toBe(1000)

    expect(calls[0].method).toBe('GET')
    expect(calls[1].method).toBe('POST')
    expect(calls[1].json).toEqual({ title: 'New Ticket Title', body: 'New ticket description' })
    expect(calls[2].method).toBe('POST')
  })

  it('validates required field: detail.subject', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    calls = (fetch as any).calls

    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, subject: undefined as any } }

    await expect(handle(payload as any, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.subject')
    expect(calls.length).toBe(0)
  })

  it('validates required field: detail.description', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    calls = (fetch as any).calls

    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, description: undefined as any } }

    await expect(handle(payload as any, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.description')
    expect(calls.length).toBe(0)
  })

  it('validates required field: detail.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    calls = (fetch as any).calls

    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, id: undefined as any } }

    await expect(handle(payload as any, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.id')
    expect(calls.length).toBe(0)
  })

  it('throws on non-2xx GitHub list issues response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Bad credentials' }, 401))
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'Test', description: 'Desc', id: '1' },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('GitHub list issues failed: 401 Unauthorized at https://api.github.com/repos/octocat/example/issues?per_page=100')
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx GitHub create issue response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ items: [] })
      return jsonResponse({ message: 'Validation failed' }, 422)
    })
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'New', description: 'Desc', id: '1' },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('GitHub create issue failed: 422 Unprocessable Entity at https://api.github.com/repos/octocat/example/issues')
    expect(calls.length).toBe(2)
  })

  it('throws on non-2xx Zendesk comment response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ items: [] })
      if (req.method === 'POST' && req.url.includes('/repos/')) return jsonResponse({ number: 1, html_url: 'https://github.com/octocat/example/issues/1' }, 201)
      return jsonResponse({ error: 'Forbidden' }, 403)
    })
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'New', description: 'Desc', id: '1' },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Zendesk create comment failed: 403 Forbidden at https://testsub.zendesk.com/api/v2/tickets/1/comments.json')
    expect(calls.length).toBe(3)
  })

  it('uses injected fetch from config', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ items: [] })
      if (req.url.includes('/repos/')) return jsonResponse({ number: 1, html_url: 'https://github.com/octocat/example/issues/1' }, 201)
      return jsonResponse({ comment: { id: 1, body: 'x', public: true } })
    })
    calls = (fetch as any).calls

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: 'New', description: 'Desc', id: '1' },
    }

    await handle(payload, { ...baseConfig, fetch })
    expect(calls.length).toBe(3)
  })
})

